"""Pending original vsprintf dispatcher/parser/output engine, 2231–3018."""
def register(topic,q,detail):
    def lesson(title,symbol,why,principle,use,reading,qa,cards):
        topic(title,'관찰·디버깅','lib/vsprintf.c',symbol,why,principle,use,reading,
              *(q(*x) for x in qa),details=[detail(*x) for x in cards])
    lesson('Pointer Format 분배·Suffix와 Rust 계약','pointer',
      '다양한 pointer 표시 기능을 공통 switch로 연결할 때 format과 실제 객체 타입의 계약을 배웁니다.',
      'pointer는 첫 suffix에 따라 symbol·resource·hex·bitmap·MAC·IP·escape·UUID·va·권한·feature·주소·파일·날짜·clock·flags·firmware 표시 함수로 분배합니다. O와 f는 fmt+1을 전달합니다. x는 실제 주소, e는 error pointer일 때 오류 표현 아니면 기본 pointer입니다. k/u의 s는 직접 vsnprintf에서 string이며 임의 user 접근 probing을 하지 않습니다. A는 Rust 설정 확인 뒤 Rust argument formatter로 연결합니다.',
      'Format이 요구하는 실제 객체 타입과 수명을 caller가 맞춥니다. %pA는 Rust fmt::Arguments용이며 C 코드에서 임의 자료를 전달하지 않습니다. 직접 출력의 %pus를 안전한 copy_from_user API로 해석하지 않습니다.',
      'switch 선택, O/f의 한 문자 이동, e 판정, A 설정과 k/u s를 읽으세요.',
      [('일반 pointer에 e suffix를 사용하면?', '기본 pointer 정책으로 표시한다','무조건 오류 번호로 역참조한다','IS_ERR가 false이면 default_pointer입니다. Error 표현은 실제 error pointer일 때만 선택합니다.'),
       ('직접 vsnprintf의 pus는 사용자 주소를 자동 안전 probing하는가?', 'string helper로 연결되므로 caller 접근 계약이 필요하다','모든 user fault를 copy_from_user로 처리한다','k/u의 s branch는 string을 호출합니다. Tracing 호출에서의 probing 문맥과 직접 formatter 사용을 구분합니다.')],
      [('Symbol Descriptor','S/s는 dereference_symbol_descriptor 뒤 B와 공통 symbol_string으로 갑니다. Architecture 함수 descriptor 조정을 일반 문자열 역참조와 구분합니다.'),
       ('No Hash 설정','no_hash_pointers_enable은 이미 켜져 있으면 0으로 반환하고 첫 설정에서는 flag를 true로 바꾼 뒤 원본의 안내를 출력합니다. Early param은 전체 default_pointer 정책과 연결됩니다.'),
       ('API 문서 연결','원본은 pointer 확장 변경 시 printk-formats 문서와 checkpatch 검사를 함께 갱신하도록 안내합니다. 분배 switch와 관련 문서의 format 계약을 함께 관리합니다.')])
    lesson('Format Decoder·중단 후 재개하는 상태','format_decode',
      '출력 형식 파서가 별표 인자를 받기 위해 중간 결과를 반환하고 다음 호출에서 이어 읽는 원리를 배웁니다.',
      '일반 문자열을 % 전까지 반환한 뒤 flags·width·precision·qualifier·conversion을 읽습니다. Width의 *에서는 FORMAT_TYPE_WIDTH로 조기 반환하고 caller가 인자를 채운 다음 precision label부터 재개합니다. Precision의 *도 FORMAT_TYPE_PRECISION으로 반환한 뒤 qualifier부터 재개합니다. Negative width는 LEFT와 양수 폭으로 바꾸고 negative precision은 0으로 바꿉니다.',
      '같은 printf_spec 상태를 호출 사이에 유지하고 returned read만큼 format pointer를 이동합니다. 모든 token이 한 호출에서 완성된다고 가정하지 않습니다. Literal 폭의 숫자 누적과 가변 인자의 setter 경로를 구분합니다.',
      'WIDTH/PRECISION 재개 branch, 반환 read, label과 flag 누적을 읽으세요.',
      [('Width 별표에서 반환된 다음 caller가 하는 일은?', 'int 인자를 spec에 채우고 다시 decode한다','decoder가 va_list를 직접 읽는다','이 함수는 format과 spec만 받습니다. 실제 가변 인자 소비는 상위 engine에서 수행합니다.'),
       ('별표 width가 음수이면 다음 decode는?', '양수 폭과 LEFT를 설정한다','즉시 무조건 INVALID로 만든다','WIDTH 재개 branch가 부호를 바꾸고 LEFT를 OR합니다. Field 출력 방향을 함께 선택합니다.')],
      [('작은 상태기계','spec.type이 출력 대상의 타입뿐 아니라 파서의 중간 상태도 표현합니다. WIDTH→PRECISION→최종 타입 경로를 실제 read 길이와 함께 따라갑니다.'),
       ('길이 Modifier','hh/h/l/ll/L/z/t를 내부 enum으로 바꿉니다. Unsigned/signed enum의 인접 값과 SIGN=1 전제를 BUILD_BUG_ON으로 확인하여 타입 선택을 계산합니다.'),
       ('지원 범위','Float format과 n은 지원하지 않습니다. 모르는 conversion은 경고와 INVALID를 반환하며 일반 C 라이브러리 모든 format 문법을 그대로 제공하지 않습니다.')])
    lesson('Format 크기 Setter·Bit Field 절단 검사','set_field_width',
      '작은 bit field에 큰 int를 넣을 때 대입 결과를 비교해 표현 범위 초과를 감지하는 방식을 배웁니다.',
      'set_field_width는 24bit signed field에 width를 대입하고 저장된 값이 원래 int와 다르면 경고 뒤 ±FIELD_WIDTH_MAX로 clamp합니다. set_precision도 16bit signed precision 대입 뒤 다르면 0부터 PRECISION_MAX로 제한합니다. 표현 가능한 negative precision은 decoder의 재개 단계에서 0으로 바뀝니다.',
      '가변 width·precision 인자를 채우는 engine 경로에서 사용합니다. 저장 타입과 원래 타입의 범위를 구분합니다. 이 setter가 literal skip_atoi 경로의 모든 overflow와 bit field 절단까지 자동 처리한다고 설명하지 않습니다.',
      '대입→원래 값 비교→clamp와 decoder의 후속 음수 처리를 연결하세요.',
      [('Width가 저장 범위를 넘으면 어떻게 감지하는가?', '대입된 field 값과 원래 width를 비교한다','sizeof만 같으면 언제나 성공한다','작은 field에 대입하면서 값이 달라질 수 있습니다. 원래 int와 비교해 손실을 확인합니다.'),
       ('Precision의 초과 양수 값에 적용하는 상한은?', 'PRECISION_MAX이다','FIELD_WIDTH_MAX와 언제나 같다','Precision은 16bit signed,field width는 24bit signed입니다. 서로 다른 한도를 사용합니다.')],
      [('표현 경계','FIELD_WIDTH_MAX=(1<<23)-1,PRECISION_MAX=(1<<15)-1입니다. Signed 필드의 음수 표현과 clamp 정책이 항상 대칭인 것은 아닙니다.'),
       ('상태와 검사의 위치','Setter는 byte buffer를 할당하지 않습니다. 표현할 숫자 형식의 상태값을 제한하며 실제 출력 공간 검사와는 다른 역할입니다.')])
    lesson('Vsnprintf Engine·인자 승격과 필요한 길이','vsnprintf',
      '작은 formatter들을 하나의 engine으로 연결하면서 자료 타입, 저장 공간, 결과 길이의 계약을 배웁니다.',
      'Size>INT_MAX를 조기 거부하고 spec을 초기화합니다. Decode 결과에 따라 일반 문자열·별표 int·char·string·pointer·percent·숫자를 처리합니다. Char/short 계열은 int로 va_arg한 뒤 좁은 타입으로 cast합니다. Pointer는 helper 출력 뒤 alphanumeric suffix를 모두 건너뜁니다. INVALID이면 더 이상 인자를 읽지 않고 종료합니다. Size>0이면 실제 끝 안 또는 end[-1]에 NUL을 저장하고 필요한 길이 str-buf를 반환합니다.',
      'Format과 실제 가변 인자 타입을 맞추고 size에 종료 byte 공간도 포함합니다. 반환>=size이면 잘림입니다. 반환 길이를 실제 저장량처럼 사용해 다음 pointer를 무조건 전진시키지 않습니다. Size0의 길이 계산에도 유효 format과 인자는 필요합니다.',
      'type switch, 작은 타입 int 승격, suffix skip, INVALID stop, 최종 NUL을 읽으세요.',
      [('size=4에 abcdef를 출력하면 반환과 저장은?', '반환 6,저장은 abc와 NUL이다','반환 3,저장은 abcdef 전부이다','필요한 길이는 6이고 종료 byte를 포함한 실제 용량에는 앞 세 문자만 남습니다.'),
       ('hhd 값은 va_arg로 signed char를 직접 읽는가?', 'int로 읽은 뒤 signed char로 바꾼다','항상 signed char로 직접 읽는다','C 가변 인자에서 작은 정수는 int로 승격됩니다. 원본도 그 계약으로 읽습니다.')],
      [('INVALID 뒤 정지','지원하지 않는 format 뒤에 계속 va_arg하면 나머지 format과 인자 목록이 어긋날 수 있습니다. 원본은 goto out으로 전체 출력을 멈춥니다.'),
       ('별표 Precision 차이','Negative precision은 이 구현에서 0이 됩니다. 일반 libc의 negative precision 처리와 같은 것으로 가정하지 않습니다. Decimal precision과 ZERO flag 조합도 원본 동작으로 확인합니다.'),
       ('Suffix 소비','Pointer 확장 뒤의 alphanumeric 문자를 모두 소비합니다. 평문을 바로 붙이면 suffix로 삼을 수 있으므로 separator와 format 계약을 지킵니다.')])
    lesson('Scnprintf·실제 저장 길이와 Zero 공간','vscnprintf',
      '같은 출력 결과라도 반환 길이의 계약을 바꾸는 wrapper가 buffer 이어쓰기에 어떤 영향을 주는지 배웁니다.',
      'vscnprintf는 size=0이면 인자를 출력 함수에 넘기지 않고 0을 반환합니다. 그 외 vsnprintf의 i를 받고 i<size이면 i, 아니면 size-1을 반환합니다. scnprintf는 va_start→vscnprintf→va_end로 일반 가변 호출을 감쌉니다. Snprintf wrapper는 필요한 전체 길이를 그대로 반환합니다.',
      '필요한 전체 길이를 구할 때와 실제 buffer에 쓴 길이를 구할 때 API를 선택합니다. 반환 계약을 혼동해 짧은 buffer 뒤로 넘어가지 않습니다. Size가 유효 범위 안이라는 원본 engine 계약도 함께 확인합니다.',
      'size0 조기 반환, i<size, size-1, 두 가변 wrapper를 읽으세요.',
      [('size=4에 abcdef를 scnprintf로 출력하면 반환은?', '3이다','6이다','종료 byte를 제외하고 실제로 쓴 세 문자를 반환합니다. Snprintf의 필요한 길이와 다릅니다.'),
       ('vscnprintf의 size0 경로는?', '바로 0을 반환한다','vsnprintf를 반드시 호출해 모든 인자를 소비한다','원본은 함수 앞에서 size0을 검사합니다. 이 경로는 내부 vsnprintf를 호출하지 않습니다.')],
      [('공통 결과','두 계열은 같은 bounded engine을 사용하므로 일반적인 저장 문자열은 같습니다. 반환값을 보고 다음 동작을 정하는 caller의 계약이 다릅니다.'),
       ('Int와 Size','vsnprintf는 size>INT_MAX에서 0을 반환합니다. 정상 bounded 출력의 반환 규칙을 임의 거대 size에 대한 성공 보장으로 확대하지 않습니다.')])
    lesson('Sprintf Wrapper·Capacity 없는 호출의 전제','vsprintf',
      'Bounded engine을 이용하더라도 caller 용량을 전달하지 않는 wrapper에는 별도의 공간 전제가 남는다는 점을 배웁니다.',
      'vsprintf는 vsnprintf에 INT_MAX를 전달합니다. Sprintf도 va_start와 va_end 사이 같은 engine에 INT_MAX를 전달합니다. 실제 caller buffer 크기를 알아내거나 계산하는 코드가 없고 원본 문서는 overflow 방지를 위해 bounded 계열 사용을 안내합니다.',
      '이 원본 wrapper의 동작을 이해하되 새 코드의 고정 buffer 출력에는 실제 용량을 전달하는 snprintf·scnprintf 계약을 사용합니다. 내부 함수 이름에 n이 있다는 이유로 caller의 작은 저장공간이 자동 보호된다고 생각하지 않습니다.',
      '두 INT_MAX 전달과 wrapper의 인자 정리를 읽으세요.',
      [('32byte buffer를 sprintf에 전달하면 engine이 아는 capacity는?', 'wrapper가 넘긴 INT_MAX이다','자동으로 32를 검출한다','실제 object size를 얻는 부분이 없습니다. Caller 공간과 넘긴 size가 일치한다는 보장이 없습니다.'),
       ('실제 용량을 전달할 수 있는 대응 함수는?', 'snprintf 또는 scnprintf이다','skip_atoi이다','Bounded 출력 계열은 caller가 size를 제공합니다. 반환이 필요한 길이인지 저장 길이인지도 선택합니다.')],
      [('Wrapper도 API','한 줄 wrapper도 중요한 계약을 바꿉니다. 알고리즘 body를 재사용하는 것과 buffer의 실제 크기를 알고 있는 것은 다릅니다.'),
       ('실행 시험 범위','충분한 임시 공간에 정상 format을 넣어 wrapper 결과를 검증할 수 있습니다. 임의 작은 공간 overflow를 의도적으로 만들어 학습 진도 데이터를 위험하게 하지 않습니다.')])
